//! Experimental ten-hertz navigation task over the unchanged fifty-hertz flight pilot.
use super::{arena::{Arena,Movement,layout::Surface},sight::{Sight,Contact},flight_control::{FlightGoal,FlightPilot}};
use bevy::math::{Dir2,Dir3,Vec2,Vec3};
use bevy_gym::{Env,robots::{DroneHover,DroneObstacle,DroneObservation}};
use std::time::Duration;

#[derive(Clone,Copy,Debug)]
pub enum Route {Stationary,Lateral,Approach,House,Pipe}
pub struct Task {
 arena:Arena,drone:DroneHover,sight:Sight,previous_visible:Option<Vec3>,velocity:Vec3,
 route:Route,right:bool,back:bool,stage:usize,hold:u32,pub steps:u32,pub visible:u32,pub first_seen:Option<u32>,pub ended:bool,pub score:f32,
}
impl Task {
 pub fn new(seed:u64,route:Route)->Self {
  let arena=Arena::default();
  let obstacles=arena.blocks().iter().filter(|b|b.surface!=Surface::Floor).map(|b|DroneObstacle::try_from((b.centre,b.half,b.rotation)).unwrap());
  let mut drone=DroneHover::with_obstacles(obstacles);drone.reset(Some(seed));
  Self{arena,drone,sight:Sight::default(),previous_visible:None,velocity:Vec3::ZERO,route,right:true,back:false,stage:0,hold:0,steps:0,visible:0,first_seen:None,ended:false,score:0.0}
 }
 pub fn contact(&self)->Contact{self.sight.contact()}
 pub fn observation(&self)->DroneObservation{self.drone.observation()}
 fn rays(&self)->[(Vec3,f32);8]{
  let current=self.observation();let forward=current.orientation()*Vec3::NEG_Z;
  let forward=Vec3::new(forward.x,0.0,forward.z).normalize_or_zero();let right=Vec3::new(-forward.z,0.0,forward.x);
  std::array::from_fn(|index|{
   let angle=index as f32*std::f32::consts::TAU/8.0;let direction=right*angle.cos()+forward*angle.sin();
   let distance=[-0.4_f32,0.0,0.4].into_iter().map(|height|{let from=current.position()+Vec3::Y*height;self.arena.obstruction(from,from+direction*3.0).unwrap_or(3.0)}).fold(3.0_f32,f32::min);
   (direction,distance)
  })
 }
 pub fn features(&self)->Vec<f32>{
  let obs=self.observation();let inverse=obs.orientation().inverse();let body_velocity=inverse*obs.linear_velocity()/4.0;
  let gravity=inverse*Vec3::Y;let angular=obs.angular_velocity()/4.0;let forward=obs.orientation()*Vec3::NEG_Z;
  let mut input=vec![obs.position().y/3.0];input.extend(body_velocity.to_array());input.extend(gravity.to_array());input.extend(angular.to_array());input.extend([forward.x,forward.z,obs.position().x/10.0,obs.position().z/10.0]);
  let (point,flags,age)=match self.sight.contact(){Contact::Unknown=>(obs.position(),[1.0,0.0,0.0],0.0),Contact::Visible(p)=>(p,[0.0,1.0,0.0],0.0),Contact::Remembered{point,age}=>(point,[0.0,0.0,1.0],age.as_secs_f32()/3.0)};
  input.extend((inverse*(point-obs.position())/10.0).to_array());input.extend(flags);input.push(age);input.extend((inverse*self.velocity/4.0).to_array());input.extend(self.rays().map(|(_,range)|range/3.0));assert_eq!(input.len(),32);input
 }
 pub fn teacher(&self)->Vec<f32>{
  let obs=self.observation();let current=obs.position();let forward=obs.orientation()*Vec3::NEG_Z;
  let (position,yaw)=match self.sight.contact(){
   Contact::Unknown=>(Vec3::new(current.x,2.5,current.z),0.5),
   contact=>{
    let (point,age)=match contact{Contact::Visible(point)=>(point,0.0),Contact::Remembered{point,age}=>(point,age.as_secs_f32()),Contact::Unknown=>unreachable!()};
    let point=point+self.velocity*(age+0.5);let direction=Vec3::new(point.x-current.x,0.0,point.z-current.z).normalize_or_zero();
    (Vec3::new(point.x,2.5,point.z)-direction*5.0,forward.cross(direction).y.atan2(forward.dot(direction)))
   }
  };
  let mut displacement=(position-current).clamp_length_max(3.0);
  for (direction,distance) in self.rays(){if distance<2.0{displacement-=direction*(2.0-distance)*2.0;}}
  let body=obs.orientation().inverse()*displacement.clamp_length_max(3.0)/3.0;
  vec![body.x,body.y,body.z,yaw/std::f32::consts::PI]
 }
 pub fn goal_action(&self,position:Vec3,heading:Vec3)->Vec<f32>{
  let obs=self.observation();let displacement=(position-obs.position()).clamp_length_max(3.0);let body=obs.orientation().inverse()*displacement/3.0;let direction=heading.normalize();vec![body.x,body.y,body.z,direction.x,direction.z]
 }
 pub fn advance(&mut self,action:&[f32],pilot:&FlightPilot)->f32{
  assert!(!self.ended&&self.steps<3000);assert_eq!(action.len(),5);assert!(action.iter().all(|v|v.is_finite()&&(-1.0..=1.0).contains(v)));
  let obs=self.observation();let position=(obs.position()+obs.orientation()*Vec3::new(action[0],action[1],action[2])*3.0).clamp(Vec3::new(-9.5,1.0,-9.5),Vec3::new(9.5,4.0,9.5));
  let forward=obs.orientation()*Vec3::NEG_Z;let current=Dir2::new(Vec2::new(forward.x,forward.z)).unwrap_or(Dir2::X);let heading=Dir2::new(Vec2::new(action[3],action[4])).unwrap_or(current);
  let goal=FlightGoal::try_from((position,heading)).unwrap();self.advance_goal(goal,pilot)
 }
 pub fn advance_goal(&mut self,goal:FlightGoal,pilot:&FlightPilot)->f32{
  assert!(!self.ended&&self.steps<3000);let mut reward=0.0;
  for _ in 0..5 {
   let character=self.arena.position();if character.x>6.0{self.right=false;}if character.x < -6.0{self.right=true;}if character.z<3.0{self.back=true;}if character.z>9.0{self.back=false;}
   let movement=if self.steps<250{Movement::Idle}else{match self.route{Route::Stationary=>Movement::Idle,Route::Lateral=>if self.right{Movement::Right}else{Movement::Left},Route::Approach=>if self.back{Movement::Backward}else{Movement::Forward},
     Route::House|Route::Pipe=>{
      let points=match self.route{Route::House=>[Vec3::new(0.0,0.0,-3.0),Vec3::new(-5.0,0.0,-3.0),Vec3::new(-5.0,0.0,-1.0),Vec3::new(-1.0,0.0,-3.0),Vec3::new(0.0,0.0,9.0)],_=>[Vec3::new(5.0,0.0,6.0),Vec3::new(5.0,0.0,1.0),Vec3::new(5.0,0.0,-4.0),Vec3::new(0.0,0.0,-4.0),Vec3::new(0.0,0.0,9.0)]};
      let current=self.arena.position();let delta=points[self.stage%5]-Vec3::new(current.x,0.0,current.z);
      if delta.length()<0.2{if self.stage%5==1{self.hold+=1;}else{self.stage+=1;self.hold=0;}Movement::Idle}else{Movement::from([delta.z < -0.12,delta.z>0.12,delta.x < -0.12,delta.x>0.12])}
     }}};self.arena.step(movement);
   let step=self.drone.step(pilot.action(self.observation(),goal).unwrap());self.steps+=1;self.ended=step.is_done();
   let obs=self.observation();let orientation=obs.orientation();let contact=self.sight.sample(&self.arena,obs.position()+orientation*Vec3::new(0.0,0.0,-0.22),Dir3::new(orientation*Vec3::NEG_Z).unwrap(),self.arena.position(),Duration::from_millis(20));
   if let Contact::Visible(point)=contact{
    if let Some(previous)=self.previous_visible{let delta=point-previous;self.velocity=(Vec3::new(delta.x,0.0,delta.z)/0.02).clamp_length_max(4.0);}
    self.previous_visible=Some(point);self.visible+=1;self.first_seen.get_or_insert(self.steps);
    let error=point.distance(obs.position())-5.0;reward+=(1.0/(1.0+error*error/9.0))/5.0;
   }else{self.previous_visible=None;}
   if matches!(contact,Contact::Unknown){self.velocity=Vec3::ZERO;}
   if self.ended{reward-=5.0;break;}
  }
  self.score+=reward;reward
 }
 pub fn trace(&self)->serde_json::Value{serde_json::json!({"time_seconds":self.steps as f32*0.02,"drone_metres":self.observation().position().to_array(),"target_metres":self.arena.position().to_array(),"visible":matches!(self.sight.contact(),Contact::Visible(_)),"stage":self.stage,"hold":self.hold})}
 pub fn result(&self)->serde_json::Value{serde_json::json!({"route":format!("{:?}",self.route),"steps":self.steps,"visible":self.visible,"first_seen":self.first_seen,"ended":self.ended,"score":self.score})}
}

//! Research baseline: static-map path planning receives only own pose and filtered sight.
use super::{flight_control::FlightGoal,layout,sight::Contact};
use bevy::math::{Dir2,Vec2,Vec3};
use bevy_gym::robots::DroneObservation;
use rapier3d::{prelude::*,parry::query::ShapeCastOptions};
use std::time::Duration;
const SIDE:usize=39;
const INTERVAL:Duration=Duration::from_millis(100);
/// Investigation stores one finite observed point, never the target's current hidden pose.
struct LastSeen{point:Vec3,velocity:Vec3,remaining:Duration}
/// Navigation owns static geometry and bounded memory; it cannot read the character.
pub struct Navigator{map:Map,focus:Option<LastSeen>,previous:Option<Vec3>,searched:Vec<Option<Duration>>,elapsed:Duration,scan:f32,heading:Option<Dir2>}
impl Default for Navigator{fn default()->Self{let map=Map::default();let searched=vec![None;map.targets.len()];Self{map,focus:None,previous:None,searched,elapsed:Duration::ZERO,scan:std::f32::consts::FRAC_PI_2,heading:None}}}
impl Navigator{
 pub fn goal(&mut self,own:DroneObservation,contact:Contact)->FlightGoal{
  self.elapsed+=INTERVAL;
  match contact{
   Contact::Visible(point) if point.is_finite()=>{let velocity=self.previous.map_or(Vec3::ZERO,|previous|{let d=(point-previous)/INTERVAL.as_secs_f32();Vec3::new(d.x,0.0,d.z).clamp_length_max(4.0)});self.previous=Some(point);self.focus=Some(LastSeen{point,velocity,remaining:Duration::from_secs(10)});},
   _=>{self.previous=None;if let Some(focus)=&mut self.focus{focus.remaining=focus.remaining.saturating_sub(INTERVAL);}},
  }
  if self.focus.as_ref().is_some_and(|focus|focus.remaining.is_zero()){self.focus=None;}
  let position=own.position();let forward=own.orientation()*Vec3::NEG_Z;
  if self.elapsed==INTERVAL{self.scan=forward.z.atan2(forward.x);}
  for (index,&point) in self.map.targets.iter().enumerate(){let delta=point-position;let distance=delta.length();if distance<=20.0&&forward.dot(delta)>=std::f32::consts::FRAC_1_SQRT_2*distance&&self.map.visible(position,point){self.searched[index]=Some(self.elapsed);}}
  let hold=Vec3::new(position.x.clamp(-9.5,9.5),2.0,position.z.clamp(-9.5,9.5));
  let current=match contact{Contact::Visible(point) if point.is_finite()=>Some(point),_=>None};
  let target=if let Some(point)=current{Some(point)}else if self.elapsed<Duration::from_secs(8)&&self.focus.is_none(){None}else{
   let centre=self.focus.as_ref().map_or(position,|focus|focus.point+focus.velocity*(Duration::from_secs(10)-focus.remaining).as_secs_f32().min(1.0));
   self.map.targets.iter().enumerate().filter(|(index,_)|self.searched[*index].is_none_or(|time|self.elapsed-time>Duration::from_secs(10))).min_by(|(ia,a),(ib,b)|a.distance_squared(centre).total_cmp(&b.distance_squared(centre)).then(ia.cmp(ib))).map(|(_,point)|*point)
  };
  let (goal,heading)=if let Some(target)=target{
   let delta=target-position;let heading=Dir2::new(Vec2::new(delta.x,delta.z)).unwrap_or(Dir2::Y);
   let lead=if current.is_some(){self.focus.as_ref().map_or(Vec3::ZERO,|focus|focus.velocity*0.5)}else{Vec3::ZERO};
   (self.map.viewpoint(position,target+lead).unwrap_or(hold),heading)
  }else{self.scan=(self.scan+0.1)%std::f32::consts::TAU;(hold,Dir2::new(Vec2::new(self.scan.cos(),self.scan.sin())).unwrap())};
  let previous=self.heading.unwrap_or_else(||Dir2::new(Vec2::new(forward.x,forward.z)).unwrap_or(Dir2::Y));
  let turn=previous.perp_dot(*heading).atan2(previous.dot(*heading)).clamp(-0.1,0.1);
  let heading=Dir2::new(bevy::math::Rot2::radians(turn)* *previous).unwrap();self.heading=Some(heading);
  FlightGoal::try_from((goal,heading)).unwrap()
 }
}
/// Query-only world; graph cells describe conservative sphere clearance at two metres.
struct Map{world:PhysicsWorld,sphere:SharedShape,body:SharedShape,points:Vec<Vec3>,free:Vec<bool>,edges:Vec<Vec<usize>>,targets:Vec<Vec3>}
impl Default for Map{
 fn default()->Self{
  let mut world=PhysicsWorld::default();for block in layout::blocks(){world.insert(RigidBodyBuilder::fixed().translation(Vector::from_array(block.centre.to_array())).rotation(Vector::from_array(block.rotation.to_scaled_axis().to_array())),ColliderBuilder::cuboid(block.half.x,block.half.y,block.half.z));}world.step();
  let points=(0..SIDE*SIDE).map(|index|Vec3::new(index as f32%SIDE as f32*0.5-9.5,2.0,(index/SIDE) as f32*0.5-9.5)).collect();
  let mut map=Self{world,sphere:SharedShape::ball(0.9),body:SharedShape::ball(0.45),points,free:vec![false;SIDE*SIDE],edges:vec![Vec::new();SIDE*SIDE],targets:Vec::new()};
  let target_shape=SharedShape::ball(0.1);for x in -9..=9{for z in -9..=9{let point=Vec3::new(x as f32,1.0,z as f32);let pose=Pose::from_translation(Vector::from_array(point.to_array()));if map.world.intersect_shape(pose,target_shape.as_ref(),QueryFilter::default()).next().is_none(){map.targets.push(point);}}}
  for index in 0..SIDE*SIDE{map.free[index]=map.clear(map.points[index],map.points[index]);}
  for index in 0..SIDE*SIDE{if !map.free[index]{continue;}let x=index%SIDE;let z=index/SIDE;
   for (dx,dz) in [(-1,0),(1,0),(0,-1),(0,1)]{let nx=x as i32+dx;let nz=z as i32+dz;if !(0..SIDE as i32).contains(&nx)||!(0..SIDE as i32).contains(&nz){continue;}let next=nz as usize*SIDE+nx as usize;if map.free[next]&&map.clear(map.points[index],map.points[next]){map.edges[index].push(next);}}
  }map
 }
}
impl Map{
 /// Rapier 0.36 cast time is the unit interval; the vector is total displacement in metres.
 fn clear(&self,from:Vec3,to:Vec3)->bool{self.clear_shape(from,to,self.sphere.as_ref())}
 fn clear_shape(&self,from:Vec3,to:Vec3,shape:&dyn Shape)->bool{
  if !from.is_finite()||!to.is_finite(){return false;}
  let pose=Pose::from_translation(Vector::from_array(from.to_array()));
  if self.world.intersect_shape(pose,shape,QueryFilter::default()).next().is_some(){return false;}
  let delta=to-from;if delta.length_squared()<1e-10{return true;}
  self.world.cast_shape(&pose,Vector::from_array(delta.to_array()),shape,ShapeCastOptions{max_time_of_impact:1.0,stop_at_penetration:true,..Default::default()},QueryFilter::default()).is_none()
 }
 fn visible(&self,from:Vec3,to:Vec3)->bool{
  let delta=to-from;let distance=delta.length();if !distance.is_finite()||distance<=f32::EPSILON{return false;}
  self.world.cast_ray(&Ray::new(Vector::from_array(from.to_array()),Vector::from_array((delta/distance).to_array())),distance,true,QueryFilter::default()).is_none()
 }
 /// Pick a reachable viewing cell, then a clear shortcut no longer than 2.5 metres.
 fn viewpoint(&self,from:Vec3,target:Vec3)->Option<Vec3>{
  let escaping=!self.clear(from,from);let mut root=None;let mut nearest=f32::INFINITY;
  for (index,&point) in self.points.iter().enumerate(){let distance=point.distance_squared(from);if self.free[index]&&distance<nearest&&(self.clear(from,point)||(escaping&&self.clear_shape(from,point,self.body.as_ref()))){root=Some(index);nearest=distance;}}
  let root=root?;if escaping{return Some(self.points[root]);}let mut previous=vec![None;self.points.len()];let mut distances=vec![f32::INFINITY;self.points.len()];let mut queue=Vec::with_capacity(self.points.len());queue.push(root);previous[root]=Some(root);distances[root]=nearest.sqrt();let mut head=0;
  while head<queue.len(){let index=queue[head];head+=1;for &next in &self.edges[index]{if previous[next].is_none(){previous[next]=Some(index);distances[next]=distances[index]+0.5;queue.push(next);}}}
  let mut best=None;let mut score=f32::INFINITY;
  for index in queue{let point=self.points[index];let range=point.distance(target);let candidate=distances[index]+(range-6.0).abs()*2.0;if (2.0..=12.0).contains(&range)&&candidate<score&&self.visible(point,target){best=Some(index);score=candidate;}}
  let mut current=best?;let mut route=vec![current];while current!=root{current=previous[current]?;route.push(current);}route.reverse();
  let mut next=self.points[root];for index in route{let point=self.points[index];if point.distance(from)<=2.5&&self.clear(from,point){next=point;}}
  Some(next)
 }
}

//! Research baseline: static-map path planning receives only own pose and filtered sight.
use super::{flight_control::FlightGoal,layout,sight::Contact};
use bevy::math::{Dir2,Vec2,Vec3};
use bevy_gym::robots::DroneObservation;
use rapier3d::{prelude::*,parry::query::ShapeCastOptions};
use std::time::Duration;
const SIDE:usize=39;
const INTERVAL:Duration=Duration::from_millis(100);
/// Investigation stores one finite observed point, never the target's current hidden pose.
struct LastSeen{point:Vec3,remaining:Duration}
/// Navigation owns static geometry and bounded memory; it cannot read the character.
pub struct Navigator{map:Map,focus:Option<LastSeen>,scan:f32}
impl Default for Navigator{fn default()->Self{Self{map:Map::default(),focus:None,scan:std::f32::consts::FRAC_PI_2}}}
impl Navigator{
 pub fn goal(&mut self,own:DroneObservation,contact:Contact)->FlightGoal{
  match contact{
   Contact::Visible(point) if point.is_finite()=>self.focus=Some(LastSeen{point,remaining:Duration::from_secs(10)}),
   Contact::Remembered{point,age} if point.is_finite()=>self.focus=Some(LastSeen{point,remaining:Duration::from_secs(10).saturating_sub(age)}),
   _=>if let Some(focus)=&mut self.focus{focus.remaining=focus.remaining.saturating_sub(INTERVAL);},
  }
  if self.focus.as_ref().is_some_and(|focus|focus.remaining.is_zero()){self.focus=None;}
  let position=own.position();let hold=Vec3::new(position.x.clamp(-9.5,9.5),2.0,position.z.clamp(-9.5,9.5));
  let (goal,heading)=if let Some(focus)=&self.focus{
   let delta=focus.point-position;let heading=Dir2::new(Vec2::new(delta.x,delta.z)).unwrap_or(Dir2::Y);
   (self.map.viewpoint(position,focus.point).unwrap_or(hold),heading)
  }else{self.scan=(self.scan+0.05)%std::f32::consts::TAU;(hold,Dir2::new(Vec2::new(self.scan.cos(),self.scan.sin())).unwrap())};
  FlightGoal::try_from((goal,heading)).unwrap()
 }
}
/// Query-only world; graph cells describe conservative sphere clearance at two metres.
struct Map{world:PhysicsWorld,sphere:SharedShape,points:Vec<Vec3>,free:Vec<bool>,edges:Vec<Vec<usize>>}
impl Default for Map{
 fn default()->Self{
  let mut world=PhysicsWorld::default();for block in layout::blocks(){world.insert(RigidBodyBuilder::fixed().translation(Vector::from_array(block.centre.to_array())).rotation(Vector::from_array(block.rotation.to_scaled_axis().to_array())),ColliderBuilder::cuboid(block.half.x,block.half.y,block.half.z));}world.step();
  let points=(0..SIDE*SIDE).map(|index|Vec3::new(index as f32%SIDE as f32*0.5-9.5,2.0,(index/SIDE) as f32*0.5-9.5)).collect();
  let mut map=Self{world,sphere:SharedShape::ball(0.9),points,free:vec![false;SIDE*SIDE],edges:vec![Vec::new();SIDE*SIDE]};
  for index in 0..SIDE*SIDE{map.free[index]=map.clear(map.points[index],map.points[index]);}
  for index in 0..SIDE*SIDE{if !map.free[index]{continue;}let x=index%SIDE;let z=index/SIDE;
   for (dx,dz) in [(-1,0),(1,0),(0,-1),(0,1)]{let nx=x as i32+dx;let nz=z as i32+dz;if !(0..SIDE as i32).contains(&nx)||!(0..SIDE as i32).contains(&nz){continue;}let next=nz as usize*SIDE+nx as usize;if map.free[next]&&map.clear(map.points[index],map.points[next]){map.edges[index].push(next);}}
  }map
 }
}
impl Map{
 /// Rapier 0.36 cast time is the unit interval; the vector is total displacement in metres.
 fn clear(&self,from:Vec3,to:Vec3)->bool{
  if !from.is_finite()||!to.is_finite(){return false;}
  let pose=Pose::from_translation(Vector::from_array(from.to_array()));
  if self.world.intersect_shape(pose,self.sphere.as_ref(),QueryFilter::default()).next().is_some(){return false;}
  let delta=to-from;if delta.length_squared()<1e-10{return true;}
  self.world.cast_shape(&pose,Vector::from_array(delta.to_array()),self.sphere.as_ref(),ShapeCastOptions{max_time_of_impact:1.0,stop_at_penetration:true,..Default::default()},QueryFilter::default()).is_none()
 }
 fn visible(&self,from:Vec3,to:Vec3)->bool{
  let delta=to-from;let distance=delta.length();if !distance.is_finite()||distance<=f32::EPSILON{return false;}
  self.world.cast_ray(&Ray::new(Vector::from_array(from.to_array()),Vector::from_array((delta/distance).to_array())),distance,true,QueryFilter::default()).is_none()
 }
 /// Pick a reachable viewing cell, then a clear shortcut no longer than 2.5 metres.
 fn viewpoint(&self,from:Vec3,target:Vec3)->Option<Vec3>{
  let mut root=None;let mut nearest=f32::INFINITY;
  for (index,&point) in self.points.iter().enumerate(){let distance=point.distance_squared(from);if self.free[index]&&distance<nearest&&self.clear(from,point){root=Some(index);nearest=distance;}}
  let root=root?;let mut previous=vec![None;self.points.len()];let mut distances=vec![f32::INFINITY;self.points.len()];let mut queue=Vec::with_capacity(self.points.len());queue.push(root);previous[root]=Some(root);distances[root]=nearest.sqrt();let mut head=0;
  while head<queue.len(){let index=queue[head];head+=1;for &next in &self.edges[index]{if previous[next].is_none(){previous[next]=Some(index);distances[next]=distances[index]+0.5;queue.push(next);}}}
  let mut best=None;let mut score=f32::INFINITY;
  for index in queue{let point=self.points[index];let range=point.distance(target);let candidate=distances[index]+(range-4.0).abs()*2.0;if (2.0..=12.0).contains(&range)&&candidate<score&&self.visible(point,target){best=Some(index);score=candidate;}}
  let mut current=best?;let mut route=vec![current];while current!=root{current=previous[current]?;route.push(current);}route.reverse();
  let mut next=self.points[root];for index in route{let point=self.points[index];if point.distance(from)<=2.5&&self.clear(from,point){next=point;}}
  Some(next)
 }
}

//! Research baseline: static-map path planning receives only own pose and filtered sight.
use super::{flight_control::FlightGoal,layout,sight::Contact};
use bevy::math::{Dir2,Vec2,Vec3};
use bevy_gym::robots::DroneObservation;
use rapier3d::{prelude::*,parry::query::ShapeCastOptions};
use std::time::Duration;
const SIDE:usize=39;
const INTERVAL:Duration=Duration::from_millis(100);
/// Investigation stores one finite observed point, never the target's current hidden pose.
