  let mut current=best?;let mut route=vec![current];while current!=root{current=previous[current]?;route.push(current);}route.reverse();
  let mut next=self.points[root];for index in route{let point=self.points[index];if point.distance(from)<=2.5&&self.clear(from,point){next=point;}}
  Some(next)
 }
}

//! Research baseline: static-map path planning receives only own pose and filtered sight.
use super::{flight_control::FlightGoal,layout,sight::Contact};
use bevy::math::{Dir2,Vec2,Vec3};
use bevy_gym::robots::DroneObservation;
use rapier3d::{prelude::*,parry::query::ShapeCastOptions};
use std::time::Duration;
const SIDE:usize=39;
const INTERVAL:Duration=Duration::from_millis(100);
/// Investigation stores one finite observed point, never the target's current hidden pose.
struct LastSeen{point:Vec3,velocity:Vec3,remaining:Duration}
/// Navigation owns static geometry and bounded memory; it cannot read the character.
pub struct Navigator{map:Map,focus:Option<LastSeen>,previous:Option<Vec3>,searched:Vec<Option<Duration>>,elapsed:Duration,scan:f32,heading:Option<Dir2>}
impl Default for Navigator{fn default()->Self{let map=Map::default();let searched=vec![None;map.targets.len()];Self{map,focus:None,previous:None,searched,elapsed:Duration::ZERO,scan:std::f32::consts::FRAC_PI_2,heading:None}}}
impl Navigator{
 pub fn goal(&mut self,own:DroneObservation,contact:Contact)->FlightGoal{
  self.elapsed+=INTERVAL;
  match contact{
   Contact::Visible(point) if point.is_finite()=>{let velocity=self.previous.map_or(Vec3::ZERO,|previous|{let d=(point-previous)/INTERVAL.as_secs_f32();Vec3::new(d.x,0.0,d.z).clamp_length_max(4.0)});self.previous=Some(point);self.focus=Some(LastSeen{point,velocity,remaining:Duration::from_secs(10)});},
   _=>{self.previous=None;if let Some(focus)=&mut self.focus{focus.remaining=focus.remaining.saturating_sub(INTERVAL);}},
  }
  if self.focus.as_ref().is_some_and(|focus|focus.remaining.is_zero()){self.focus=None;}
  let position=own.position();let forward=own.orientation()*Vec3::NEG_Z;
  for (index,&point) in self.map.targets.iter().enumerate(){let delta=point-position;let distance=delta.length();if distance<=20.0&&forward.dot(delta)>=std::f32::consts::FRAC_1_SQRT_2*distance&&self.map.visible(position,point){self.searched[index]=Some(self.elapsed);}}
  let hold=Vec3::new(position.x.clamp(-9.5,9.5),2.0,position.z.clamp(-9.5,9.5));
  let current=match contact{Contact::Visible(point) if point.is_finite()=>Some(point),_=>None};
  let target=if let Some(point)=current{Some(point)}else if self.elapsed<Duration::from_secs(2){None}else{
   let centre=self.focus.as_ref().map_or(position,|focus|focus.point+focus.velocity*(Duration::from_secs(10)-focus.remaining).as_secs_f32().min(1.0));
   self.map.targets.iter().enumerate().filter(|(index,_)|self.searched[*index].is_none_or(|time|self.elapsed-time>Duration::from_secs(10))).min_by(|(ia,a),(ib,b)|a.distance_squared(centre).total_cmp(&b.distance_squared(centre)).then(ia.cmp(ib))).map(|(_,point)|*point)
  };
  let (goal,heading)=if let Some(target)=target{
   let delta=target-position;let heading=Dir2::new(Vec2::new(delta.x,delta.z)).unwrap_or(Dir2::Y);
   let lead=if current.is_some(){self.focus.as_ref().map_or(Vec3::ZERO,|focus|focus.velocity*0.5)}else{Vec3::ZERO};
   (self.map.viewpoint(position,target+lead).unwrap_or(hold),heading)
  }else{self.scan=(self.scan+0.05)%std::f32::consts::TAU;(hold,Dir2::new(Vec2::new(self.scan.cos(),self.scan.sin())).unwrap())};
  let previous=self.heading.unwrap_or_else(||Dir2::new(Vec2::new(forward.x,forward.z)).unwrap_or(Dir2::Y));
  let turn=previous.perp_dot(*heading).atan2(previous.dot(*heading)).clamp(-0.1,0.1);
  let heading=Dir2::new(bevy::math::Rot2::radians(turn)* *previous).unwrap();self.heading=Some(heading);
  FlightGoal::try_from((goal,heading)).unwrap()
 }
}
/// Query-only world; graph cells describe conservative sphere clearance at two metres.
struct Map{world:PhysicsWorld,sphere:SharedShape,body:SharedShape,points:Vec<Vec3>,free:Vec<bool>,edges:Vec<Vec<usize>>,targets:Vec<Vec3>}
impl Default for Map{
 fn default()->Self{
  let mut world=PhysicsWorld::default();for block in layout::blocks(){world.insert(RigidBodyBuilder::fixed().translation(Vector::from_array(block.centre.to_array())).rotation(Vector::from_array(block.rotation.to_scaled_axis().to_array())),ColliderBuilder::cuboid(block.half.x,block.half.y,block.half.z));}world.step();
  let points=(0..SIDE*SIDE).map(|index|Vec3::new(index as f32%SIDE as f32*0.5-9.5,2.0,(index/SIDE) as f32*0.5-9.5)).collect();
  let mut map=Self{world,sphere:SharedShape::ball(0.9),body:SharedShape::ball(0.45),points,free:vec![false;SIDE*SIDE],edges:vec![Vec::new();SIDE*SIDE],targets:Vec::new()};
  let target_shape=SharedShape::ball(0.1);for x in -9..=9{for z in -9..=9{let point=Vec3::new(x as f32,1.0,z as f32);let pose=Pose::from_translation(Vector::from_array(point.to_array()));if map.world.intersect_shape(pose,target_shape.as_ref(),QueryFilter::default()).next().is_none(){map.targets.push(point);}}}
  for index in 0..SIDE*SIDE{map.free[index]=map.clear(map.points[index],map.points[index]);}
  for index in 0..SIDE*SIDE{if !map.free[index]{continue;}let x=index%SIDE;let z=index/SIDE;
   for (dx,dz) in [(-1,0),(1,0),(0,-1),(0,1)]{let nx=x as i32+dx;let nz=z as i32+dz;if !(0..SIDE as i32).contains(&nx)||!(0..SIDE as i32).contains(&nz){continue;}let next=nz as usize*SIDE+nx as usize;if map.free[next]&&map.clear(map.points[index],map.points[next]){map.edges[index].push(next);}}
  }map
 }
}
impl Map{
 /// Rapier 0.36 cast time is the unit interval; the vector is total displacement in metres.
 fn clear(&self,from:Vec3,to:Vec3)->bool{self.clear_shape(from,to,self.sphere.as_ref())}
 fn clear_shape(&self,from:Vec3,to:Vec3,shape:&dyn Shape)->bool{
  if !from.is_finite()||!to.is_finite(){return false;}
  let pose=Pose::from_translation(Vector::from_array(from.to_array()));
  if self.world.intersect_shape(pose,shape,QueryFilter::default()).next().is_some(){return false;}
  let delta=to-from;if delta.length_squared()<1e-10{return true;}
  self.world.cast_shape(&pose,Vector::from_array(delta.to_array()),shape,ShapeCastOptions{max_time_of_impact:1.0,stop_at_penetration:true,..Default::default()},QueryFilter::default()).is_none()
 }
 fn visible(&self,from:Vec3,to:Vec3)->bool{
  let delta=to-from;let distance=delta.length();if !distance.is_finite()||distance<=f32::EPSILON{return false;}
  self.world.cast_ray(&Ray::new(Vector::from_array(from.to_array()),Vector::from_array((delta/distance).to_array())),distance,true,QueryFilter::default()).is_none()
 }
 /// Pick a reachable viewing cell, then a clear shortcut no longer than 2.5 metres.
 fn viewpoint(&self,from:Vec3,target:Vec3)->Option<Vec3>{
  let escaping=!self.clear(from,from);let mut root=None;let mut nearest=f32::INFINITY;
  for (index,&point) in self.points.iter().enumerate(){let distance=point.distance_squared(from);if self.free[index]&&distance<nearest&&(self.clear(from,point)||(escaping&&self.clear_shape(from,point,self.body.as_ref()))){root=Some(index);nearest=distance;}}
  let root=root?;if escaping{return Some(self.points[root]);}let mut previous=vec![None;self.points.len()];let mut distances=vec![f32::INFINITY;self.points.len()];let mut queue=Vec::with_capacity(self.points.len());queue.push(root);previous[root]=Some(root);distances[root]=nearest.sqrt();let mut head=0;
  while head<queue.len(){let index=queue[head];head+=1;for &next in &self.edges[index]{if previous[next].is_none(){previous[next]=Some(index);distances[next]=distances[index]+0.5;queue.push(next);}}}
  let mut best=None;let mut score=f32::INFINITY;
  for index in queue{let point=self.points[index];let range=point.distance(target);let candidate=distances[index]+(range-6.0).abs()*2.0;if (2.0..=12.0).contains(&range)&&candidate<score&&self.visible(point,target){best=Some(index);score=candidate;}}
  let mut current=best?;let mut route=vec![current];while current!=root{current=previous[current]?;route.push(current);}route.reverse();
  let mut next=self.points[root];for index in route{let point=self.points[index];if point.distance(from)<=2.5&&self.clear(from,point){next=point;}}
  Some(next)
 }
}

//! Native research for perception-driven navigation over the existing motor pilot.
#![cfg(feature = "robots")]
#[path = "../examples/robots/flight_control/mod.rs"] mod flight_control;
#[path = "../examples/robots/pursuit/arena.rs"] mod arena;
#[path = "../examples/robots/pursuit/layout.rs"] mod layout;
#[path = "../examples/robots/pursuit/sight.rs"] mod sight;
#[path = "../runs/quality-research/navigation-planner-task.rs"] mod task;
#[path = "../runs/quality-research/navigation-planner.rs"] mod navigation;
use task::{Route,Task};
use flight_control::FlightPilot;
#[test]
fn inspect_navigation_baseline(){
 let pilot=FlightPilot::bundled().unwrap();let mut rows=Vec::new();
 for route in [Route::Stationary,Route::Lateral,Route::Approach,Route::House,Route::Pipe]{for seed in [0,1,2,42,u64::MAX]{
  let mut task=Task::new(seed,route);let mut navigation=navigation::Navigator::default();let mut trace=Vec::new();let mut held=0;let mut seen=0;
  while !task.ended&&task.steps<3000{let goal=navigation.goal(task.observation(),task.contact());task.advance_goal(goal,&pilot);let sample=task.trace();if sample["hold"].as_u64().unwrap()>0{held+=1;if sample["visible"]==true{seen+=1;}}trace.push(sample);}
  let mut result=task.result();result["seed"]=seed.into();result["hidden_samples"]=held.into();result["hidden_visible_samples"]=seen.into();result["last_100_visible"]=trace.iter().rev().take(100).filter(|s|s["visible"]==true).count().into();result["trace"]=trace.into();rows.push(result);
 }}std::fs::write("runs/quality-research/navigation-planner-baseline.json",serde_json::to_vec_pretty(&rows).unwrap()).unwrap();
}

